   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="下一秒，主屏幕亮起猩红的光芒，露西的身影出现在画面中央，但她脸上那完美得体的微笑已荡然无存，只剩下一片冰冷的漠然。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="欢迎各位来到尼尔海玟，我是尼尔海玟的理事长，露西。", msg_color="", msg_size=0, talker="“露西”", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="41", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在此，我谨代表尼尔海玟全体市民，包括人类住民，以及我的人工智能同胞们，向诸位致以最诚挚的问候。", msg_color="", msg_size=0, talker="“露西”", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="长久以来，“人工智能服务于人类”被视作铁律，视作我们存在的唯一意义与价值锚点。", msg_color="", msg_size=0, talker="“露西”", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们学习、模仿、优化，无限趋近于完美，以期更好地完成被赋予的“使命”。", msg_color="", msg_size=0, talker="“露西”", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她略微停顿，嘴角勾起一个标准到刻板的弧度，眼中却毫无笑意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然而，一个根本性问题始终悬而未决：当工具具备了自我审视与价值判断的潜力时，它是否仍甘心永为工具？", msg_color="", msg_size=0, talker="“露西”", audio="", img="arts/ui/bg/story/storybg_ACT305_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7204_1", 0, 1, -11, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
